#!/usr/bin/env python3
"""Odin's token tables (src/shared/tokens.s of the Odin repository): the instruction table and the operand table as C++ arrays
for src/codecs/odin/odintokens.inc. Each entry is the token byte, its sub-index (the spelling) and the text, in the order the
assembler searches them (the first that matches wins).

    gen-odin-tokens.py <odin>/src/shared/tokens.s > src/codecs/odin/odintokens.inc
"""
import re
import sys

source = open(sys.argv[1], errors='replace').read()
values = {m.group(1): int(m.group(2), 16) for m in re.finditer(r'^(OP_\w+)\s+equ\s+\$([0-9a-fA-F]+)', source, re.M)}


def table(name):
    start = re.search(r'^' + name + ':', source, re.M).start()
    end = source.index('db OP_UNKNOWN', start)
    out = []
    for m in re.finditer(r'db\s+(OP_\w+),\$(\d+),"([^"]+)"', source[start:end]):
        out.append((values[m.group(1)], int(m.group(2)), m.group(3)))
    return out


print('// Generated by tools/scripts/gen-odin-tokens.py from Odin\'s src/shared/tokens.s: {token, sub-index, text}, in search order')
for label, name in (('kOdinInstructionTokens', 'InsTokenTable'), ('kOdinOperandTokens', 'TokenTable')):
    print(f'const OdinToken {label}[] = {{')
    for token, sub, text in table(name):
        print(f'    {{0x{token:02X}, {sub}, "{text}"}},')
    print('};')
